\cref{thm:sparse-removal-odd-cycles} may be compared to \cite[Proposition 4.2]{conlon2021regularity}, which can be recovered by taking $k = 2$ and $p \gg n^{-1/2}$. The dense pairs condition in \cite[Proposition 4.2]{conlon2021regularity} is more restrictive, since:
\begin{itemize} 
    \item[(1).] It applies to all partitions with at most $M$ parts, while our condition only concerns partitions with large parts (and one can always take $M = 1/\tau$);
    \item[(2).] It includes the contribution of the diagonal pairs $(V_i, V_i)$.
\end{itemize} 
Point $(1)$ will be relevant for \cref{cor:subgraphs-pseudorandom}, while $(2)$ will be relevant for \cref{cor:graphs-few-4-cycles,cor:smooth-free-graphs}.

 \label{cor:graphs-few-4-cycles}
Fix integers $j \ge 1$, $k \ge 2$, $\ell \ge 3$. For any $p \ge n^{-1/2}$ and any $n$-vertex graph $G$ with $O(p^4 n^4)$ $C_4$'s, the following hold true.
\begin{itemize}
    \item[$(i)$.] If $G$ has $o(p^{j} n^{j+1})$ $P_{j}$'s, then it has $o(pn^2)$ edges.
    \item[$(ii)$.] If $G$ has $o(p^{2\ell}n^{2\ell})$ $C_{2\ell}$'s, then it has $o(pn^2)$ edges.
    \item[$(iii)$.] If $G$ has $o(p^{2k+1} n^{2k+1})$ $C_{2k+1}$'s and every bipartite subgraph of $G$ has at most $o(p^4n^4)$ $C_4$'s,
    then $G$ can be made $\{C_3, C_5, \ldots, C_{2k+1}\}$-free by removing $o(pn^2)$ edges.
\end{itemize}

Parts $(i)$ and $(ii)$ of \cref{cor:graphs-few-4-cycles} follow from \cref{thm:expected-cycles-paths}, while part $(iii)$ follows from \cref{thm:sparse-removal-odd-cycles}; the latter generalizes the fact that 
\begin{itemize}
    \item[$(iii').$] \emph{If $G$ has $o(p^4n^4)$ $C_4$'s and $o(p^{2k+1} n^{2k+1})$ $C_{2k+1}$'s, then it can be made $\{C_3, C_5, \ldots, C_{2k+1}\}$-free by removing $o(pn^2)$ edges.}
\end{itemize}
When $2k+1 = 5$, $(iii')$ recovers the main result of Conlon, Fox, Sudakov and Zhao's first aforementioned paper (see \cite[Theorem 1.2]{conlon2021regularity}). For a general $k$, $(iii')$ essentially follows from the same authors' follow-up work on counting lemmas in $C_4$-free graphs. 
Another generalization of $(iii')$, which applies to $k$-partite graphs (as required in arithmetic applications), is given in \cref{cor:k-cycle-removal-few-4-cycles}.

 \label{cor:linear-patterns-pseudorandom}
For any $\epsilon, C > 0$ and $k, \ell \in \mathbf{Z}$ with $k > 2\ell \ge 4$, there exists $\delta > 0$ such that the following holds. Let $a_1, \ldots, a_k$ be nonzero integers with $a_1 + \cdots + a_k = 0$, $G$ be an abelian group of order $n$ with $\gcd(n, a_1 \cdots a_k) = 1$, and $S \subset G$, $\nu : G \to [0, \infty)$ satisfy
\begin{itemize}
    \item[$(i)$] \emph{($\nu$ majorizes $\mathbbm{1}_S$ after scaling).}  $\epsilon \mathbbm{1}_S \le \frac{|S|}{n}\nu$,
    \item[$(ii)$] \emph{($\nu$ is mildly-pseudorandom).}  $||\nu||_{S^{2\ell}} \le C$ and $||\nu - 1||_{\substack{ \\ \square}} \le \delta$. 
\end{itemize}
Then $S$ contains $\ge \delta |S|^k/n$ solutions in $x_1, \ldots, x_k$ to the linear equation $a_1 x_1 + \cdots + a_k x_k = 0$.

 \label{cor:linear-patterns-generalized-Sidon}
For any $\epsilon, C > 0$, $k \in \mathbf{Z}_{\ge 5}$, and nonzero integers $a_1, \ldots, a_k$ with $a_1 + \cdots + a_k = 0$, there exists $\delta > 0$ such that the following holds. Let $n \in \mathbf{Z}_{\ge 1}$ and $S \subset [n]$ satisfy
\begin{itemize}
    \item[$(i)$] \emph{($S$ is large).} $|S| \ge \epsilon n^{1/2}$,
    \item[$(ii)$] \emph{(Sidon-type condition).} For each $h \neq 0$, $S$ contains at most $C$ pairs of the form $(x, x+h)$.  
\end{itemize}
Then $S$ contains $\ge \delta |S|^k/n$ solutions in $x_1, \ldots, x_k$ to the linear equation $a_1 x_1 + \cdots + a_k x_k = 0$.

 \label{cor:polygonal-patterns}

For any $\epsilon > 0$, $k \in \mathbf{Z}_{\ge 5}$, and slopes $s_i \in \mathbf{Q} \cup \{\infty\}$ with $s_i \neq s_{i+1}$ for $i \in \mathbf{Z}/k\mathbf{Z}$, there exists $\delta > 0$ such that the following holds. Let $n \in \mathbf{Z}_{\ge 1}$ and $S \subset [n] \times [n]$ satisfy
\begin{itemize}
    \item[$(i)$] \emph{($S$ is large).} $|S| \ge \epsilon n^{3/2}$,
    \item[$(ii)$] \emph{(Few parallelograms).} For each $i \in \mathbf{Z}/k\mathbf{Z}$, $S$ contains at most $\delta |S|^4/n^4$ non-degenerate $(s_i, s_{i+1}, s_i, s_{i+1})$-polygons.
\end{itemize}
Then $S$ contains at least $\delta |S|^k / n^k$ (possibly degenerate) $(s_1, \ldots, s_k)$-polygons.

