 \label{lem:Schatten-norms-matrices}
For $q, q_i, r \in [1, \infty]$ and any suitably-sized complex matrices $M, A_1, \ldots, A_k$, the following hold true.
\begin{itemize}
    \item[$(i)$.] \emph{(Norm)} $||\cdot||_{S^q}$ is a unitary-invariant norm on $\mathbf{C}^{m \times n}$, and $||M||_{S^q} = ||M^T||_{S^q} = ||M^*||_{S^q}$.
    \item[$(ii)$.] \emph{(Monotonicity and interpolation)} For $q_0 < q_1$, one has $||M||_{S^{q_0}} \ge ||M||_{S^{q_1}}$. Moreover, for $\theta \in [0, 1]$ and $\frac{1}{q_\theta} := \frac{1-\theta}{q_0} + \frac{\theta}{q_1}$, one has 
    \[
        ||M||_{S^{q_\theta}} \le ||M||_{S^{q_0}}^{1-\theta} \cdot  ||M||_{S^{q_1}}^{\theta}.
    \]
    \item[$(iii)$.] \emph{(Special cases)} $||M||_{S^\infty}$ is the spectral ($L^2$ operator) norm of $M$, often written $||M||$ or $||M||_2$, while $||M||_{S^2}$ is the $L^2$ norm on the entries of $M$ (also known as the Frobenius norm). More generally, one has $||M||_{S^{2k}}^{2k} = \textnormal{Tr}((MM^*)^k)$ for $k \in \mathbf{Z}_{\ge 1}$. In particular, if $M$ is the adjacency matrix of an undirected graph $G$ and $k \ge 2$, then $||M||_{S^{2k}}^{2k} = \textnormal{Hom}(C_{2k}, G)$.
    \item[$(iv)$.] \emph{(Doubling property)} One has
    \begin{equation} \label{eq:halfing}
        ||M||_{S^q} = ||MM^*||_{S^{q/2}}^{1/2}.
    \end{equation}
    \item[$(v)$.] \emph{(H\"older-type inequality)} If $\frac{1}{r} = \frac{1}{q_1} + \cdots + \frac{1}{q_k}$, one has $||A_1 \cdots A_k||_{S^r} \le ||A_1||_{S^{q_1}} \cdots ||A_k||_{S^{q_k}}$. In particular, given any diagonal matrix $I_A$ with entries in $\{0, 1\}$, and any partitions $\mathcal{P}, \mathcal{R}$ of a suitably-sized set such that $\mathcal{R}$ is finer than or equal to $\mathcal{P}$, one has
    \begin{equation} \label{eq:ignore-averaging}
        \max\left(||I_A M||_{S^r},\ ||A_{\mathcal{P}}M||_{S^r},\ ||(A_{\mathcal{R}} - A_{\mathcal{P}})M||_{S^r} \right) \le ||M||_{S^r}.
    \end{equation}
    \item[$(vi)$.] \emph{(Trace norm inequality)} When $q = 1$, $||M||_{S^1}$ (also known as the trace norm or nuclear norm) satisfies
    \[
        |\textnormal{Tr}(M)| \le ||M||_{S^1}.
    \]
\end{itemize}

